 49	    public Reservation createReservation(int roomNumber, String guestName, String guestEmail, String guestCpf,
 50	                                        LocalDate checkIn, LocalDate checkOut, int guests, String ratePlan) {
 51	        Room room = rooms.get(roomNumber);
 52	        if (room == null) {
 53	            return null;
 54	        }
 55	
 56	        if (guests < 1 || guests > room.getCapacity()) {
 57	            return null;
 58	        }
 59	
 60	        if (!checkOut.isAfter(checkIn)) {
 61	            return null;
 62	        }
 63	
 64	        if (!isRoomAvailable(roomNumber, checkIn, checkOut, null)) {
 65	            return null;
 66	        }
 67	
 68	        double[] nightlyPrices = PricingService.calculateNightlyPrices(room.getNightlyRate(), checkIn, checkOut);
 69	        int nights = nightlyPrices.length;
 70	        double subtotal = PricingService.calculateSubtotal(nightlyPrices);
 71	        double discount = PricingService.calculateDiscount(subtotal, ratePlan);
 72	        double total = PricingService.calculateTotal(subtotal, discount);
 73	
 74	        Reservation reservation = new Reservation(
 75	            nextReservationId++,
 76	            roomNumber,
 77	            guestName,
 78	            guestEmail,
 79	            guestCpf,
 80	            checkIn,
 81	            checkOut,
 82	            guests,
 83	            RatePlan.valueOf(ratePlan),
 84	            nights,
 85	            subtotal,
 86	            discount,
 87	            total
 88	        );
 89	
 90	        reservations.put(reservation.getId(), reservation);
 91	        return reservation;
 92	    }
