292	    private boolean isRoomAvailable(int roomNumber, LocalDate checkIn, LocalDate checkOut, Integer excludeReservationId) {
293	        for (Reservation res : reservations.values()) {
294	            if (excludeReservationId != null && res.getId() == excludeReservationId) {
295	                continue;
296	            }
297	
298	            if (res.getRoomNumber() != roomNumber || res.getStatus() == ReservationStatus.CANCELLED) {
299	                continue;
300	            }
301	
302	            if (!checkOut.isAfter(res.getCheckIn()) || !res.getCheckOut().isAfter(checkIn)) {
303	                continue;
304	            }
305	
306	            return false;
307	        }
308	
309	        return true;
310	    }
