381	    private static void createReservation(Context ctx, ReservationService service) {
382	        try {
383	            Map<String, Object> body = gson.fromJson(ctx.body(), Map.class);
384	
385	            if (!body.containsKey("roomNumber") || !body.containsKey("guestName") ||
386	                !body.containsKey("guestEmail") || !body.containsKey("guestCpf") ||
387	                !body.containsKey("checkIn") || !body.containsKey("checkOut") ||
388	                !body.containsKey("guests") || !body.containsKey("ratePlan")) {
389	                ctx.status(400);
390	                ctx.json(Map.of("error", "INVALID_REQUEST", "message", "Missing required fields"));
391	                return;
392	            }
393	
394	            int roomNumber = ((Number) body.get("roomNumber")).intValue();
395	            String guestName = (String) body.get("guestName");
396	            String guestEmail = (String) body.get("guestEmail");
397	            String guestCpf = (String) body.get("guestCpf");
398	            String checkInStr = (String) body.get("checkIn");
399	            String checkOutStr = (String) body.get("checkOut");
400	            int guests = ((Number) body.get("guests")).intValue();
401	            String ratePlan = (String) body.get("ratePlan");
402	
403	            try {
404	                LocalDate checkIn = LocalDate.parse(checkInStr, DateTimeFormatter.ISO_DATE);
405	                LocalDate checkOut = LocalDate.parse(checkOutStr, DateTimeFormatter.ISO_DATE);
406	
407	                if (guests < 1) {
408	                    ctx.status(400);
409	                    ctx.json(Map.of("error", "INVALID_REQUEST", "message", "Guests must be at least 1"));
410	                    return;
411	                }
412	
413	                if (!checkOut.isAfter(checkIn)) {
414	                    ctx.status(400);
415	                    ctx.json(Map.of("error", "INVALID_REQUEST", "message", "Check-out must be after check-in"));
416	                    return;
417	                }
418	
419	                Room room = service.getRooms().stream()
420	                    .filter(r -> r.getNumber() == roomNumber)
421	                    .findFirst()
422	                    .orElse(null);
423	
424	                if (room == null) {
425	                    ctx.status(404);
426	                    ctx.json(Map.of("error", "ROOM_NOT_FOUND", "message", "Room not found"));
427	                    return;
428	                }
429	
430	                if (guests > room.getCapacity()) {
431	                    ctx.status(422);
432	                    ctx.json(Map.of("error", "CAPACITY_EXCEEDED", "message", "Room capacity exceeded"));
433	                    return;
434	                }
435	
436	                Reservation res = service.createReservation(roomNumber, guestName, guestEmail, guestCpf,
437	                    checkIn, checkOut, guests, ratePlan);
438	
439	                if (res == null) {
440	                    ctx.status(409);
441	                    ctx.json(Map.of("error", "ROOM_UNAVAILABLE", "message", "Room is not available for these dates"));
442	                    return;
443	                }
444	
445	                ctx.status(201);
446	                ctx.json(reservationToJson(res));
447	            } catch (Exception e) {
448	                ctx.status(400);
449	                ctx.json(Map.of("error", "INVALID_REQUEST", "message", "Invalid date format"));
450	            }
451	        } catch (Exception e) {
452	            ctx.status(400);
453	            ctx.json(Map.of("error", "INVALID_REQUEST", "message", "Invalid request"));
454	        }
455	    }
