  237	            .filter(r -> r.getStatus() != ReservationStatus.CANCELLED &&
  238	                        !r.getCheckIn().isAfter(date) &&
  239	                        r.getCheckOut().isAfter(date))
  240	            .sorted(Comparator.comparingInt(Reservation::getRoomNumber))
  241	            .collect(Collectors.toList());
  242	
  243	        for (Reservation res : occupiedReservations) {
  244	            Room room = rooms.get(res.getRoomNumber());
  245	            csv.append(String.format("%d,%s,%d,%s,%s\n",
  246	                res.getRoomNumber(),
  247	                room.getType(),
  248	                res.getId(),
  249	                FormatService.formatDateISO(res.getCheckIn()),
  250	                FormatService.formatDateISO(res.getCheckOut())));
  251	        }
  252	
  253	        csv.append(String.format("total,%d/%d\n", occupiedReservations.size(), rooms.size()));
  254	
  255	        return csv.toString();
  256	    }
  257	
  258	    public String getRevenueReport(YearMonth month) {
  259	        StringBuilder csv = new StringBuilder();
  260	        csv.append("reservation,room,check_in,check_out,status,amount\n");
  261	
  262	        double totalAmount = 0.0;
  263	        List<Reservation> monthReservations = reservations.values().stream()
  264	            .filter(r -> YearMonth.from(r.getCheckIn()).equals(month) &&
  265	                        (r.getStatus() == ReservationStatus.CONFIRMED ||
  266	                         r.getStatus() == ReservationStatus.CHECKED_IN ||
  267	                         r.getStatus() == ReservationStatus.CHECKED_OUT ||
  268	                         r.getStatus() == ReservationStatus.CANCELLED))
  269	            .sorted(Comparator.comparingInt((Reservation r) -> r.getCheckIn().getDayOfMonth())
  270	                            .thenComparingInt(Reservation::getId))
  271	            .collect(Collectors.toList());
  272	
  273	        for (Reservation res : monthReservations) {
  274	            double amount = res.getAmountPaid() - (res.getRefund() != null ? res.getRefund() : 0.0);
  275	            if (amount > 0 || res.getStatus() == ReservationStatus.CANCELLED) {
  276	                csv.append(String.format("%d,%d,%s,%s,%s,%s\n",
  277	                    res.getId(),
  278	                    res.getRoomNumber(),
  279	                    FormatService.formatDateISO(res.getCheckIn()),
  280	                    FormatService.formatDateISO(res.getCheckOut()),
  281	                    res.getStatus(),
  282	                    PricingService.roundHalfToEven(amount)));
  283	                totalAmount += amount;
  284	            }
  285	        }
  286	
  287	        csv.append(String.format("total,%.2f\n", PricingService.roundHalfToEven(totalAmount)));
  288	
  289	        return csv.toString();
  290	    }
  291	
  292	    private boolean isRoomAvailable(int roomNumber, LocalDate checkIn, LocalDate checkOut, Integer excludeReservationId) {
  293	        for (Reservation res : reservations.values()) {
  294	            if (excludeReservationId != null && res.getId() == excludeReservationId) {
  295	                continue;
  296	            }
  297	
  298	            if (res.getRoomNumber() != roomNumber || res.getStatus() == ReservationStatus.CANCELLED) {
  299	                continue;
  300	            }
  301	
  302	            if (!checkOut.isAfter(res.getCheckIn()) || !res.getCheckOut().isAfter(checkIn)) {
  303	                continue;
  304	            }
  305	
  306	            return false;
  307	        }
  308	
  309	        return true;
  310	    }
  311	}

