 57	    private static void getRooms(Context ctx, ReservationService service) {
 58	        List<Map<String, Object>> roomsList = new ArrayList<>();
 59	        for (Room room : service.getRooms()) {
 60	            Map<String, Object> roomMap = new LinkedHashMap<>();
 61	            roomMap.put("number", room.getNumber());
 62	            roomMap.put("type", room.getType().toString());
