 70	    private static void createReservation(Context ctx, ReservationService service) {
 71	        try {
 72	            Map<String, Object> body = gson.fromJson(ctx.body(), Map.class);
 73	
 74	            if (!body.containsKey("roomNumber") || !body.containsKey("guestName") ||
 75	                !body.containsKey("guestEmail") || !body.containsKey("guestCpf") ||
 76	                !body.containsKey("checkIn") || !body.containsKey("checkOut") ||
 77	                !body.containsKey("guests") || !body.containsKey("ratePlan")) {
 78	                ctx.status(400);
 79	                ctx.json(Map.of("error", "INVALID_REQUEST", "message", "Missing required fields"));
 80	                return;
 81	            }
 82	
 83	            int roomNumber = ((Number) body.get("roomNumber")).intValue();
 84	            String guestName = (String) body.get("guestName");
 85	            String guestEmail = (String) body.get("guestEmail");
 86	            String guestCpf = (String) body.get("guestCpf");
 87	            String checkInStr = (String) body.get("checkIn");
 88	            String checkOutStr = (String) body.get("checkOut");
 89	            int guests = ((Number) body.get("guests")).intValue();
 90	            String ratePlan = (String) body.get("ratePlan");
 91	
 92	            try {
 93	                LocalDate checkIn = LocalDate.parse(checkInStr, DateTimeFormatter.ISO_DATE);
 94	                LocalDate checkOut = LocalDate.parse(checkOutStr, DateTimeFormatter.ISO_DATE);
 95	
 96	                if (guests < 1) {
 97	                    ctx.status(400);
 98	                    ctx.json(Map.of("error", "INVALID_REQUEST", "message", "Guests must be at least 1"));
 99	                    return;
100	                }
101	
102	                if (!checkOut.isAfter(checkIn)) {
103	                    ctx.status(400);
104	                    ctx.json(Map.of("error", "INVALID_REQUEST", "message", "Check-out must be after check-in"));
105	                    return;
106	                }
107	
108	                Room room = service.getRooms().stream()
109	                    .filter(r -> r.getNumber() == roomNumber)
110	                    .findFirst()
111	                    .orElse(null);
112	
113	                if (room == null) {
114	                    ctx.status(404);
115	                    ctx.json(Map.of("error", "ROOM_NOT_FOUND", "message", "Room not found"));
116	                    return;
117	                }
118	
119	                if (guests > room.getCapacity()) {
120	                    ctx.status(422);
121	                    ctx.json(Map.of("error", "CAPACITY_EXCEEDED", "message", "Room capacity exceeded"));
122	                    return;
123	                }
124	
125	                Reservation res = service.createReservation(roomNumber, guestName, guestEmail, guestCpf,
126	                    checkIn, checkOut, guests, ratePlan);
127	
128	                if (res == null) {
129	                    ctx.status(409);
130	                    ctx.json(Map.of("error", "ROOM_UNAVAILABLE", "message", "Room is not available for these dates"));
131	                    return;
132	                }
133	
134	                ctx.status(201);
135	                ctx.json(reservationToJson(res));
136	            } catch (Exception e) {
137	                ctx.status(400);
138	                ctx.json(Map.of("error", "INVALID_REQUEST", "message", "Invalid date format"));
139	            }
140	        } catch (Exception e) {
141	            ctx.status(400);
142	            ctx.json(Map.of("error", "INVALID_REQUEST", "message", "Invalid request"));
143	        }
144	    }
