     8	public class PricingService {
     9	    private static final double HIGH_SEASON_MULTIPLIER = 1.20;
    10	    private static final double NON_REFUNDABLE_DISCOUNT_RATE = 0.15;
    11	
    12	    public static boolean isHighSeason(LocalDate date) {
    13	        int month = date.getMonthValue();
    14	        int day = date.getDayOfMonth();
    15	
    16	        if (month == 7) {
    17	            return true;
    18	        }
    19	
    20	        if (month == 12 || month == 1 || month == 2) {
    21	            return true;
    22	        }
    23	
    24	        return false;
    25	    }
    26	
    27	    public static double roundHalfToEven(double value) {
    28	        BigDecimal bd = new BigDecimal(value);
    29	        return bd.setScale(2, RoundingMode.HALF_EVEN).doubleValue();
    30	    }
    31	
    32	    public static double calculateNightlyPrice(double baseRate, LocalDate date) {
    33	        double price = baseRate;
    34	        if (isHighSeason(date)) {
    35	            price *= HIGH_SEASON_MULTIPLIER;
    36	        }
    37	        return roundHalfToEven(price);
    38	    }
    39	
    40	    public static double calculateSubtotal(double[] nightlyPrices) {
    41	        double sum = 0.0;
    42	        for (double price : nightlyPrices) {
    43	            sum += price;
    44	        }
    45	        return roundHalfToEven(sum);
    46	    }
    47	
    48	    public static double calculateDiscount(double subtotal, String ratePlan) {
    49	        if ("NON_REFUNDABLE".equals(ratePlan)) {
    50	            return roundHalfToEven(subtotal * NON_REFUNDABLE_DISCOUNT_RATE);
    51	        }
    52	        return 0.0;
    53	    }
    54	
    55	    public static double calculateTotal(double subtotal, double discount) {
    56	        return roundHalfToEven(subtotal - discount);
    57	    }
    58	
    59	    public static double[] calculateNightlyPrices(double baseRate, LocalDate checkIn, LocalDate checkOut) {
    60	        int nights = (int) java.time.temporal.ChronoUnit.DAYS.between(checkIn, checkOut);
    61	        double[] prices = new double[nights];
    62	
    63	        LocalDate current = checkIn;
    64	        for (int i = 0; i < nights; i++) {
    65	            prices[i] = calculateNightlyPrice(baseRate, current);
    66	            current = current.plusDays(1);
    67	        }
    68	
    69	        return prices;
    70	    }
    71	}
